#!/usr/bin/env python3
"""Raw HTTP client: sends exactly the bytes given, dumps exactly the bytes received."""
import socket, sys, time

def send(req_bytes, host='127.0.0.1', port=8304, timeout=5.0, wait=None):
    s = socket.create_connection((host, port), timeout=timeout)
    s.sendall(req_bytes)
    chunks = []
    s.settimeout(timeout)
    try:
        while True:
            b = s.recv(65536)
            if not b:
                break
            chunks.append(b)
    except socket.timeout:
        pass
    s.close()
    return b''.join(chunks)

if __name__ == '__main__':
    # args: port, then request read from stdin with \n -> \r\n conversion of header lines
    port = int(sys.argv[1])
    raw = sys.stdin.buffer.read()
    # convert lone \n to \r\n
    raw = raw.replace(b'\r\n', b'\n').replace(b'\n', b'\r\n')
    out = send(raw, port=port)
    sys.stdout.buffer.write(out)

#!/usr/bin/env python3
import socket, sys, os

PORT = int(os.environ.get('HCPORT', '8304'))
HOST = os.environ.get('HCHOST', '127.0.0.1')

def raw(req: bytes, port=None, host=None, timeout=5.0, keep=False):
    port = port or PORT; host = host or HOST
    s = socket.create_connection((host, port), timeout=timeout)
    s.sendall(req)
    out = b''
    try:
        while True:
            b = s.recv(65536)
            if not b: break
            out += b
    except socket.timeout:
        pass
    s.close()
    return out

def split(resp):
    i = resp.find(b'\r\n\r\n')
    if i < 0: return resp, b''
    return resp[:i], resp[i+4:]

def get(path, port=None, host=None, extra=''):
    req = f'GET {path} HTTP/1.1\r\nHost: 127.0.0.1:{port or PORT}\r\n{extra}\r\n'.encode()
    return raw(req, port, host)

def post(body, path='/', port=None, host=None, ctype='application/x-www-form-urlencoded', extra=''):
    if isinstance(body, str): body = body.encode()
    hdr = f'POST {path} HTTP/1.1\r\nHost: 127.0.0.1:{port or PORT}\r\n'
    if ctype is not None:
        hdr += f'content-type: {ctype}\r\n'
    hdr += f'content-length: {len(body)}\r\n{extra}\r\n'
    return raw(hdr.encode() + body, port, host)

if __name__ == '__main__':
    import sys
    mode = sys.argv[1]
    if mode == 'get':
        r = get(sys.argv[2])
    else:
        r = post(sys.argv[2])
    sys.stdout.buffer.write(r)
